(function () {
  // ── shared helpers (SVG, tweening) ─────────────────────────────────────────
  var NS = "http://www.w3.org/2000/svg";
  var svg = document.getElementById("scene");
  var labelEl = document.getElementById("step-label");
  var captionEl = document.getElementById("caption");

  function el(name, attrs, parent) {
    var node = document.createElementNS(NS, name);
    for (var key in attrs) node.setAttribute(key, attrs[key]);
    if (parent) parent.appendChild(node);
    return node;
  }
  function txt(parent, x, y, cls, str, anchor) {
    var t = el("text", { x: x, y: y, class: cls }, parent);
    if (anchor) t.setAttribute("text-anchor", anchor);
    t.textContent = str;
    return t;
  }
  function show(node, on) {
    node.setAttribute("opacity", on ? "1" : "0");
  }
  function place(node, x, y) {
    node.style.transform = "translate(" + x + "px," + y + "px)";
  }
  function setLine(node, x1, y1, x2, y2) {
    node.setAttribute("x1", x1);
    node.setAttribute("y1", y1);
    node.setAttribute("x2", x2);
    node.setAttribute("y2", y2);
  }
  function lerp(a, b, e) {
    return a + (b - a) * e;
  }
  function round1(v) {
    return (Math.round(v * 10) / 10).toFixed(1);
  }

  // Eased animation. fn(e) is called with e from 0 to 1. Without
  // requestAnimationFrame (or with ms = 0) it jumps straight to fn(1).
  var animTokens = {};
  function anim(key, ms, fn) {
    var token = (animTokens[key] || 0) + 1;
    animTokens[key] = token;
    if (typeof requestAnimationFrame !== "function" || ms <= 0) {
      fn(1);
      return;
    }
    var start = null;
    function frame(now) {
      if (animTokens[key] !== token) return;
      if (start === null) start = now;
      var p = Math.min(1, (now - start) / ms);
      var e = p < 0.5 ? 2 * p * p : 1 - Math.pow(-2 * p + 2, 2) / 2;
      fn(e);
      if (p < 1) requestAnimationFrame(frame);
    }
    requestAnimationFrame(frame);
  }

  // Arrowheads, one marker per colour.
  var COLORS = { g: "#1DB584", y: "#E2B44A", p: "#F472B6", b: "#38BDF8", w: "#c9dccf", r: "#F87171" };
  var defs = el("defs", {}, svg);
  Object.keys(COLORS).forEach(function (k) {
    var m = el("marker", { id: "ah-" + k, viewBox: "0 0 10 10", refX: 9, refY: 5, markerUnits: "userSpaceOnUse", markerWidth: 13, markerHeight: 13, orient: "auto" }, defs);
    el("path", { d: "M0 0 L10 5 L0 10 Z", fill: COLORS[k] }, m);
  });
  function arrow(parent, colorKey, width) {
    return el("line", { x1: 0, y1: 0, x2: 0, y2: 0, stroke: COLORS[colorKey], "stroke-width": width || 3, "marker-end": "url(#ah-" + colorKey + ")", "stroke-linecap": "round" }, parent);
  }
  function polygon(parent, cls) {
    return el("polygon", { points: "", class: cls }, parent);
  }
  function setPoly(node, pts) {
    node.setAttribute("points", pts.map(function (p) { return p[0].toFixed(1) + "," + p[1].toFixed(1); }).join(" "));
  }
  function lerpPts(a, b, e) {
    return a.map(function (p, i) { return [lerp(p[0], b[i][0], e), lerp(p[1], b[i][1], e)]; });
  }
  // Maps maths coordinates (x right, y up) to screen pixels.
  function makePlane(cx, cy, s) {
    return {
      x: function (v) { return cx + s * v; },
      y: function (v) { return cy - s * v; },
      pt: function (p) { return [cx + s * p[0], cy - s * p[1]]; },
      s: s, cx: cx, cy: cy
    };
  }
  function axes(parent, plane, xr, yr) {
    el("line", { x1: plane.x(-xr), y1: plane.y(0), x2: plane.x(xr), y2: plane.y(0), class: "axis" }, parent);
    el("line", { x1: plane.x(0), y1: plane.y(-yr), x2: plane.x(0), y2: plane.y(yr), class: "axis" }, parent);
  }

  // ── Module 3 helpers: graphs, curves, contour plane ───────────────────────
  // makeGraph maps maths values to pixels with separate x and y scales.
  function makeGraph(ox, oy, sx, sy) {
    return {
      ox: ox, oy: oy, sx: sx, sy: sy,
      x: function (v) { return ox + sx * v; },
      y: function (v) { return oy - sy * v; }
    };
  }
  function curveD(g, f, a, b, n) {
    var d = "";
    for (var i = 0; i <= n; i++) {
      var v = a + ((b - a) * i) / n;
      d += (i ? " L " : "M ") + g.x(v).toFixed(1) + " " + g.y(f(v)).toFixed(1);
    }
    return d;
  }
  function setD(node, d) {
    node.setAttribute("d", d);
  }
  function fmt(v, n) {
    return (Math.round(v * 100000) / 100000).toFixed(n === undefined ? 1 : n);
  }
  function drawAxes(parent, g, xmax, ymax, xticks, yticks) {
    el("line", { x1: g.x(0), y1: g.y(0), x2: g.x(xmax), y2: g.y(0), class: "axis" }, parent);
    el("line", { x1: g.x(0), y1: g.y(0), x2: g.x(0), y2: g.y(ymax), class: "axis" }, parent);
    (xticks || []).forEach(function (t) { txt(parent, g.x(t), g.y(0) + 15, "tick", String(t), "middle"); });
    (yticks || []).forEach(function (t) { txt(parent, g.x(0) - 7, g.y(t) + 4, "tick", String(t), "end"); });
  }
  function card(parent, x, y, w, h, cls) {
    return el("rect", { x: x, y: y, width: w, height: h, rx: 10, class: cls || "fillG" }, parent);
  }
  function ring(parent, cx, cy, rx, ry, cls) {
    return el("ellipse", { cx: cx, cy: cy, rx: rx, ry: ry, fill: "none", class: cls || "contour" }, parent);
  }
  function clipTo(id, x, y, w, h) {
    var c = el("clipPath", { id: id }, defs);
    el("rect", { x: x, y: y, width: w, height: h }, c);
  }

  // ── Module 4 helpers: seeded randomness, small shapes ─────────────────────
  function mulberry(seed) {
    var a = seed;
    return function () {
      a |= 0; a = (a + 0x6D2B79F5) | 0;
      var t = Math.imul(a ^ (a >>> 15), 1 | a);
      t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
      return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
    };
  }
  function gaussSource(rand) {
    return function () {
      var u = 1 - rand(), v = rand();
      return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * v);
    };
  }
  function box(parent, x, y, w, h, fill, stroke, r) {
    return el("rect", { x: x, y: y, width: w, height: h, rx: r === undefined ? 6 : r, fill: fill, stroke: stroke || "none", "stroke-width": 2 }, parent);
  }
  function setBox(node, x, y, w, h) {
    node.setAttribute("x", x); node.setAttribute("y", y); node.setAttribute("width", Math.max(0, w)); node.setAttribute("height", Math.max(0, h));
  }
  function vis(list, on) {
    list.forEach(function (n) { show(n, on); });
  }

  var EXPLAIN = {"joint-grid":{"h":"WHAT YOU ARE LOOKING AT","t":"Here is the **joint table** of bedrooms (X, rows) and price band (Y, columns). From this one table we can answer **two different kinds of questions**."},"marginalize-y":{"h":"MARGINAL: ADD ACROSS THE OTHER VARIABLE","t":"To study bedrooms alone, **ignore the price**: add each row across the Low and High columns. We are collapsing the Y axis."},"x-marginal":{"h":"THE MARGINAL DISTRIBUTION OF X","t":"The row totals are the **marginal distribution**: **P(X = 1) = 0.30, P(X = 2) = 0.40, P(X = 3) = 0.30**. They add up to 1. This is bedrooms over **all** houses."},"select-y":{"h":"CONDITIONAL: WE LEARN THAT Y = HIGH","t":"Now suppose we are told the house is **High priced**. Low priced houses are no longer possible, so we **keep only the High column** and drop the rest."},"conditional-slice":{"h":"SLICE OUT THE HIGH COLUMN","t":"The slice holds **0.05, 0.20 and 0.25**. These are probabilities out of **all** houses, and they add up to **0.50, not 1**. It is not yet a distribution."},"normalize":{"h":"RENORMALIZE SO IT ADDS TO 1","t":"Divide each entry by the slice total **0.50**: **0.10, 0.40, 0.50**. Now they add up to 1. This is the **conditional distribution P(X | Y = High)**."},"compare":{"h":"MARGINAL VERSUS CONDITIONAL","t":"Marginal: **0.30, 0.40, 0.30** (all houses). Conditional on High: **0.10, 0.40, 0.50**. Knowing the price **shifted the probability toward bigger houses**."},"ml-connection":{"h":"TAKEAWAY","t":"A **marginal** describes one feature on its own. **Prediction is conditioning**: observe some variables, then ask about the others, always renormalizing. The multivariate normal later does exactly this."}};
  // ── scene ──
  var steps = [
    { id: "joint-grid", label: "Start from the joint table", caption: "Here is the joint table of bedrooms (X, rows) and price band (Y, columns). From this one table we can answer two different kinds of questions." },
    { id: "marginalize-y", label: "Marginal: add across the other variable", caption: "To study bedrooms alone, ignore the price: add each row across the Low and High columns. We are collapsing the Y axis." },
    { id: "x-marginal", label: "The marginal distribution of X", caption: "The row totals are the marginal distribution: P(X = 1) = 0.30, P(X = 2) = 0.40, P(X = 3) = 0.30. They add up to 1. This is bedrooms over ALL houses." },
    { id: "select-y", label: "Conditional: we learn that Y = High", caption: "Now suppose we are told the house is High priced. Low priced houses are no longer possible, so we keep only the High column and drop the rest." },
    { id: "conditional-slice", label: "Slice out the High column", caption: "The slice holds 0.05, 0.20 and 0.25. These are probabilities out of ALL houses, and they add up to 0.50, not 1. It is not yet a distribution." },
    { id: "normalize", label: "Renormalize so it adds to 1", caption: "Divide each entry by the slice total 0.50: 0.10, 0.40, 0.50. Now they add up to 1. This is the conditional distribution P(X | Y = High)." },
    { id: "compare", label: "Marginal versus conditional", caption: "Marginal: 0.30, 0.40, 0.30 (all houses). Conditional on High: 0.10, 0.40, 0.50. Knowing the price shifted the probability toward bigger houses." },
    { id: "ml-connection", label: "Why ML cares", caption: "A marginal describes one feature on its own. Prediction is conditioning: observe some variables, then ask about the others, always re-normalizing. The multivariate normal later does exactly this." }
  ];

  var ROWS = [1, 2, 3], COLS = ["Low", "High"];
  var P = { "1,Low": 0.25, "1,High": 0.05, "2,Low": 0.20, "2,High": 0.20, "3,Low": 0.05, "3,High": 0.25 };
  var MARG = [0.30, 0.40, 0.30], SLICE = [0.05, 0.20, 0.25], COND = [0.10, 0.40, 0.50];
  var GX = 130, GY = 92, CW = 96, CH = 56;
  var RY = function (r) { return GY + r * CH; };

  var gridG = el("g", {}, svg);
  var cells = {};
  ROWS.forEach(function (r, ri) {
    COLS.forEach(function (c, ci) {
      var key = r + "," + c;
      cells[key] = box(gridG, GX + ci * CW + 3, RY(ri) + 3, CW - 6, CH - 6, "rgba(56,189,248,0.2)", "rgba(56,189,248,0.6)", 8);
      txt(gridG, GX + ci * CW + CW / 2, RY(ri) + CH / 2 + 7, "big", P[key].toFixed(2), "middle");
    });
    txt(gridG, GX - 12, RY(ri) + CH / 2 + 6, "lbl", r + (r === 1 ? " bedroom" : " bedrooms"), "end");
  });
  COLS.forEach(function (c, ci) { txt(gridG, GX + ci * CW + CW / 2, GY - 10, "big", c, "middle").setAttribute("font-size", "16"); });
  txt(gridG, GX + CW, GY - 32, "lbl lbl-p", "Y = price band", "middle");
  txt(gridG, 20, 66, "lbl lbl-y", "X = bedrooms", "start");

  // Row totals (the marginal), as a margin column.
  var MX = GX + 2 * CW + 12;
  var marginG = el("g", {}, svg);
  txt(marginG, MX + 40, GY - 10, "lbl lbl-g", "row total", "middle");
  MARG.forEach(function (m, ri) {
    box(marginG, MX, RY(ri) + 3, 80, CH - 6, "rgba(29,181,132,0.35)", "#1db584", 8);
    txt(marginG, MX + 40, RY(ri) + CH / 2 + 7, "big", m.toFixed(2), "middle");
  });
  // Arrows showing the collapse across Y.
  var collapseG = el("g", {}, svg);
  ROWS.forEach(function (r, ri) {
    var a = arrow(collapseG, "g", 3);
    setLine(a, GX + 2 * CW + 2, RY(ri) + CH / 2, MX - 2, RY(ri) + CH / 2);
  });
  txt(collapseG, MX + 40, GY + 3 * CH + 18, "lbl lbl-g", "add across Y", "middle");

  // Marginal bars.
  var RX = 450;
  var margBars = el("g", {}, svg);
  txt(margBars, RX, GY - 10, "lbl lbl-g", "marginal P(X)", "start");
  MARG.forEach(function (m, ri) {
    box(margBars, RX, RY(ri) + 10, m * 300, 36, "rgba(29,181,132,0.85)", "none", 4);
    txt(margBars, RX + m * 300 + 6, RY(ri) + 34, "lbl", m.toFixed(2), "start");
  });

  // Column total under the table, and column highlight.
  var colTot = el("g", {}, svg);
  COLS.forEach(function (c, ci) {
    box(colTot, GX + ci * CW + 3, GY + 3 * CH + 6, CW - 6, 30, "rgba(226,180,74,0.3)", "#e2b44a", 6);
    txt(colTot, GX + ci * CW + CW / 2, GY + 3 * CH + 27, "lbl", "total 0.50", "middle");
  });
  var hiBox = el("rect", { x: GX + CW + 1, y: GY - 2, width: CW - 2, height: 3 * CH + 4, rx: 10, fill: "none", stroke: "#f472b6", "stroke-width": 4 }, svg);

  // The slice, then the renormalized version.
  var sliceG = el("g", {}, svg);
  var sliceTitle = txt(sliceG, RX, GY - 10, "lbl lbl-p", "High column only", "start");
  SLICE.forEach(function (v, ri) {
    box(sliceG, RX, RY(ri) + 6, 60, CH - 12, "rgba(244,114,182,0.35)", "#f472b6", 8);
    txt(sliceG, RX + 30, RY(ri) + CH / 2 + 6, "big", v.toFixed(2), "middle");
  });
  txt(sliceG, RX + 30, GY + 3 * CH + 26, "lbl", "sum = 0.50", "middle");
  var condG = el("g", {}, svg);
  txt(condG, RX + 52, GY - 10, "lbl lbl-p", "÷ 0.50 → P(X | High)", "start");
  COND.forEach(function (v, ri) {
    box(condG, RX + 75, RY(ri) + 10, v * 110, 36, "rgba(244,114,182,0.9)", "none", 4);
    txt(condG, RX + 75 + v * 110 + 6, RY(ri) + 34, "lbl", v.toFixed(2), "start");
  });
  txt(condG, RX + 110, GY + 3 * CH + 26, "lbl lbl-g", "sum = 1.00", "middle");
  ROWS.forEach(function (r, ri) {
    var da = arrow(condG, "p", 3);
    setLine(da, RX + 64, RY(ri) + CH / 2, RX + 73, RY(ri) + CH / 2);
  });

  var cmpG = el("g", {}, svg);
  txt(cmpG, RX, GY - 10, "lbl", "bedrooms 1, 2, 3", "start");
  MARG.forEach(function (m, ri) {
    box(cmpG, RX, RY(ri) + 6, m * 220, 20, "rgba(29,181,132,0.85)", "none", 3);
    txt(cmpG, RX + m * 220 + 6, RY(ri) + 21, "note", m.toFixed(2), "start");
    box(cmpG, RX, RY(ri) + 30, COND[ri] * 220, 20, "rgba(244,114,182,0.9)", "none", 3);
    txt(cmpG, RX + COND[ri] * 220 + 6, RY(ri) + 45, "note", COND[ri].toFixed(2), "start");
  });
  el("rect", { x: RX, y: GY + 3 * CH + 14, width: 12, height: 12, fill: "rgba(29,181,132,0.85)" }, cmpG);
  txt(cmpG, RX + 18, GY + 3 * CH + 25, "note", "marginal P(X)", "start");
  el("rect", { x: RX + 100, y: GY + 3 * CH + 14, width: 12, height: 12, fill: "rgba(244,114,182,0.9)" }, cmpG);
  txt(cmpG, RX + 118, GY + 3 * CH + 25, "note", "P(X | Y = High)", "start");

  var mlG = el("g", {}, svg);
  card(mlG, 40, 40, 270, 130, "fillG");
  txt(mlG, 175, 70, "lbl lbl-g", "MARGINAL", "middle");
  txt(mlG, 175, 98, "lbl", "ignore the other variables", "middle");
  txt(mlG, 175, 120, "lbl", "(sum / collapse)", "middle");
  txt(mlG, 175, 150, "note", "a feature's overall behavior", "middle");
  card(mlG, 330, 40, 270, 130, "fillB");
  txt(mlG, 465, 70, "lbl lbl-p", "CONDITIONAL", "middle");
  txt(mlG, 465, 98, "lbl", "use what we observed", "middle");
  txt(mlG, 465, 120, "lbl", "(slice, then renormalize)", "middle");
  txt(mlG, 465, 150, "note", "prediction given the evidence", "middle");
  txt(mlG, 320, 230, "big", "Observe some variables, ask about the rest.", "middle");
  txt(mlG, 320, 258, "note", "Every probabilistic model does this, including the Gaussian ahead.", "middle");

  function render(index, id) {
    var i = index;
    show(gridG, i <= 6);
    show(collapseG, i === 1);
    show(marginG, i >= 2 && i <= 2 || i === 1);
    show(margBars, i === 2);
    show(colTot, i === 3);
    show(hiBox, i === 3 || i === 4 || i === 5);
    show(sliceG, i === 4 || i === 5);
    show(condG, i === 5);
    show(sliceTitle, i === 4);
    show(cmpG, i === 6);
    show(mlG, i === 7);
    gridG.setAttribute("opacity", i === 7 ? "0" : i === 6 ? "0.45" : "1");
    ROWS.forEach(function (r) {
      COLS.forEach(function (c) {
        var key = r + "," + c;
        var dimLow = (i >= 3 && i <= 5 && c === "Low");
        cells[key].setAttribute("opacity", dimLow ? "0.2" : "1");
        cells[key].setAttribute("fill", (i >= 3 && i <= 5 && c === "High") ? "rgba(244,114,182,0.35)" : "rgba(56,189,248,0.2)");
      });
    });
    if (i === 1) {
      anim("collapse", 1200, function (e) { collapseG.setAttribute("opacity", String(Math.min(1, e * 2))); marginG.setAttribute("opacity", String(Math.max(0, e * 2 - 1))); });
    }
  }


  // ── shared runtime: stepping, explanation panel, educational autoplay pacing, bridge ──
  var current = 0;
  var explainHeadEl = document.getElementById("explain-h");

  // **bold** markers in an explanation become <strong> nodes (built with DOM calls, never innerHTML).
  function setRich(node, str) {
    node.textContent = "";
    var parts = String(str).split("**");
    for (var i = 0; i < parts.length; i++) {
      if (parts[i] === "") continue;
      var seg = document.createElement(i % 2 ? "strong" : "span");
      seg.textContent = parts[i];
      node.appendChild(seg);
    }
  }

  function explanationFor(index) {
    var ex = (typeof EXPLAIN === "object" && EXPLAIN) ? EXPLAIN[steps[index].id] : null;
    return ex || { h: "WHAT IS HAPPENING", t: steps[index].caption };
  }

  // Autoplay pace: 4.5 to 10.5 seconds per step, longer for longer explanations, so a learner can read.
  function stepMs(index) {
    var words = String(explanationFor(index).t).replace(/\*\*/g, "").split(/\s+/).length;
    return Math.max(4500, Math.min(10500, Math.round(3800 + words * 165)));
  }

  function renderStep(index) {
    var ex = explanationFor(index);
    labelEl.textContent = steps[index].label;
    if (explainHeadEl) explainHeadEl.textContent = ex.h;
    setRich(captionEl, ex.t);
    render(index, steps[index].id);
  }

  function goTo(index) {
    if (index < 0 || index >= steps.length) return;
    current = index;
    renderStep(current);
    if (window.ReagvisBridge) window.ReagvisBridge.stepChanged(steps[current].id);
  }

  renderStep(current);

  // Autoplay: exactly one timer, one step per tick, stops on the final step.
  // PLAY on the final step restarts from the first step and plays again.
  var timer = null;

  function stopAuto() {
    if (timer !== null) {
      clearTimeout(timer);
      timer = null;
    }
  }

  function scheduleNext() {
    timer = setTimeout(function () {
      timer = null;
      if (current >= steps.length - 1) return;
      goTo(current + 1);
      if (current < steps.length - 1) scheduleNext();
    }, stepMs(current));
  }

  function startAuto() {
    if (timer !== null) return;
    if (current >= steps.length - 1) goTo(0);
    scheduleNext();
  }

  window.addEventListener("pagehide", stopAuto);

  window.ReagvisAnimation = {
    stepDuration: stepMs,
    onCommand: function (type, stepId) {
      if (type === "PLAY") startAuto();
      else if (type === "PAUSE") stopAuto();
      else if (type === "NEXT") { stopAuto(); goTo(current + 1); }
      else if (type === "PREVIOUS") { stopAuto(); goTo(current - 1); }
      else if (type === "RESET") { stopAuto(); goTo(0); }
      else if (type === "GOTO_STEP") {
        stopAuto();
        for (var i = 0; i < steps.length; i++) {
          if (steps[i].id === stepId) { goTo(i); break; }
        }
      }
    },
  };

  if (window.ReagvisBridge) {
    window.ReagvisBridge.ready();
    window.ReagvisBridge.stepChanged(steps[current].id);
  }
})();

